# main.py

import os
from flask import Flask, request, jsonify, render_template, stream_with_context, Response
import openai
import requests
from concurrent.futures import ThreadPoolExecutor, as_completed
import cachetools
import time

app = Flask(__name__)
executor = ThreadPoolExecutor(max_workers=8)
# Egyszerű memória cache 1 óra TTL-lel
cache = cachetools.TTLCache(maxsize=512, ttl=3600)

# --- API-k konfigurációja ---
OPENAI_API_KEY = os.environ.get("OPENAI_API_KEY", "sk-...")
GEMINI_API_KEY = os.environ.get("GEMINI_API_KEY", "...")
CEREBRAS_API_KEY = os.environ.get("CEREBRAS_API_KEY", "...")
EXA_API_KEY = os.environ.get("EXA_API_KEY", "...")
JINAI_API_KEY = os.environ.get("JINAI_API_KEY", "...")

openai.api_key = OPENAI_API_KEY

# --- Rate limiter EXA API-hoz ---
last_calls = []

def exa_ratelimit():
    global last_calls
    now = time.time()
    last_calls = [c for c in last_calls if now - c < 1]
    if len(last_calls) >= 5:
        time.sleep(1 - (now - last_calls[0]))
    last_calls.append(time.time())

# --- AI végpont sablonok ---
def openai_gpt4o(message):
    response = openai.ChatCompletion.create(
        model="gpt-4o",
        messages=[{"role": "user", "content": message}]
    )
    return response.choices[0].message.content

def cerebras_llama_scout(message):
    headers = {"Authorization": f"Bearer {CEREBRAS_API_KEY}", "Content-Type": "application/json"}
    payload = {"prompt": message, "model": "llama-4-scout"}
    r = requests.post("https://api.cerebras.ai/v2beta/chat", json=payload, headers=headers)
    return r.json().get("result", "")

def google_gemini(message):
    headers = {"Authorization": f"Bearer {GEMINI_API_KEY}", "Content-Type": "application/json"}
    payload = {"contents": [{"parts": [{"text": message}]}]}
    r = requests.post("https://generativelanguage.googleapis.com/v1beta/models/gemini-1.5-pro:generateContent", json=payload, headers=headers)
    return r.json().get("candidates", [{}])[0].get("content", {}).get("parts", [{}])[0].get("text", "")

def exa_search(query):
    exa_ratelimit()
    headers = {"Authorization": f"Bearer {EXA_API_KEY}"}
    r = requests.get(f"https://api.exa.ai/search?q={query}", headers=headers)
    return r.json()

def jina_search(query):
    headers = {"Authorization": f"Bearer {JINAI_API_KEY}"}
    r = requests.post("https://api.jina.ai/v1/embeddings/search", headers=headers, json={"query": query})
    return r.json()

# --- Keresési stratégiák ---
def create_search_queries(message):
    keywords = message.split()[:3]  # egyszerű kulcsszó kiválasztás
    return [message] + [f"{k} tudományos elemzés" for k in keywords][:5]

# --- Fő végpontok ---
@app.route("/")
def index():
    return render_template("index.html")

@app.route("/quickanswer", methods=['POST'])
def quickanswer():
    data = request.json
    question = data.get("question")
    cached = cache.get(("quickanswer", question))
    if cached: return jsonify({"answer": cached})
    answer = cerebras_llama_scout(question)
    cache[("quickanswer", question)] = answer
    return jsonify({"answer": answer})

@app.route("/research", methods=['POST'])
def research():
    data = request.json
    question = data.get("question")
    cached = cache.get(("research", question))
    if cached: return jsonify({"answer": cached})
    queries = create_search_queries(question)
    futures = []
    results = []
    for q in queries:
        futures.append(executor.submit(openai_gpt4o, q))
        futures.append(executor.submit(google_gemini, q))
        futures.append(executor.submit(exa_search, q))
        futures.append(executor.submit(jina_search, q))
    for future in as_completed(futures):
        try:
            results.append(future.result())
        except Exception as e:
            results.append(str(e))
    combined = "\n\n".join([str(r) for r in results])
    cache[("research", question)] = combined
    return jsonify({"answer": combined})

@app.route("/chat", methods=['POST'])
def chat():
    data = request.json
    history = data.get("history", [])
    question = data.get("question")
    msgs = [{"role": "system", "content": "Chat mód"}] + history + [{"role": "user", "content": question}]
    response = openai.ChatCompletion.create(
        model="gpt-4o",
        messages=msgs
    )
    return jsonify({"answer": response.choices[0].message.content})

@app.route("/deepresearch", methods=['POST'])
def deepresearch():
    data = request.json
    question = data.get("question")
    queries = create_search_queries(question)
    answers = []
    for q in queries:
        # Elsősorban forrásokat ad vissza
        answers.append(exa_search(q))
        time.sleep(0.2)
    return jsonify({"sources": answers})

# --- Futtatás ---
if __name__ == "__main__":
    app.run(debug=True)


